begin;
select no_plan();
select has_table('platform_private','resource_access_settings','managed projects have explicit authority settings');
select has_table('platform_private','resource_package_versions','resource membership is versioned');
select has_table('platform_private','resource_preset_versions','actions and expiry bounds are versioned');
select has_table('platform_private','resource_grants','effective grants reference immutable packages and presets');
select has_table('platform_private','resource_revocations','revocations preserve original grant history');
select has_table('platform_private','resource_access_events','resource changes have immutable audit evidence');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='platform_private' and c.relname in ('resource_access_settings','resource_package_versions','resource_preset_versions','resource_grants','resource_revocations','resource_access_events') and c.relkind='r' and c.relrowsecurity and c.relforcerowsecurity),6::bigint,'all resource authority tables force RLS');
select is((select count(*) from information_schema.role_table_grants where table_schema='platform_private' and table_name in ('resource_access_settings','resource_package_versions','resource_preset_versions','resource_grants','resource_revocations','resource_access_events') and grantee in ('anon','authenticated','service_role','PUBLIC')),0::bigint,'clients cannot administer resource authority directly');
select has_trigger('platform_private','resource_package_versions','resource_package_versions_immutable','packages retain fixed history');
select has_trigger('platform_private','resource_grants','resource_grants_immutable','grant scope cannot be overwritten');


select is((select count(*) from platform_private.resource_access_settings),0::bigint,'seeds do not silently change existing project access');
select ok(not platform_private.valid_resource_references('[]'::jsonb),'empty resource packages are rejected');
select ok(not platform_private.valid_resource_references('[{"kind":"version","dataItemId":"invalid","versionId":"invalid"}]'::jsonb),'malformed identifiers are rejected');
select ok(not platform_private.valid_resource_references('[{"kind":"external-source","sourceId":"public-a"},{"kind":"external-source","sourceId":"public-a"}]'::jsonb),'duplicate sources cannot inflate a package');
select ok(not platform_private.valid_resource_references('[{"kind":"external-source","sourceId":"public-a","secret":"hidden"}]'::jsonb),'unknown resource fields are rejected');
select ok(not platform_private.valid_resource_actions(array['content.read','content.read']),'duplicate actions are rejected');
select ok(not platform_private.valid_resource_actions(array['content.read',null]),'null actions are rejected');
select ok(not platform_private.valid_resource_actions(array['download.everything']),'unknown actions are rejected');
insert into platform_private.resource_access_settings(project_id,tenant_id,enabled_by) values('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000005');
insert into platform_private.resource_package_versions(project_id,package_id,version,name,resources,allowed_actions,license_basis,created_by) values('b2000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000001',1,'Synthetic fixed package','[{"kind":"version","dataItemId":"89000000-0000-4000-8000-000000000010","versionId":"89000000-0000-4000-8000-000000000011"}]',array['content.read'],'Synthetic test permission','10000000-0000-4000-8000-000000000005');
insert into platform_private.resource_preset_versions(project_id,preset_id,version,name,actions,max_days,approval_level,created_by) values('b2000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000002',1,'Synthetic read',array['content.read'],30,'ordinary','10000000-0000-4000-8000-000000000005');
select is((select revision from platform_private.resource_access_settings),3::bigint,'package and preset inserts advance authority revision');
select throws_ok($$update platform_private.resource_package_versions set name='Overwritten'$$,'22023',null,'an existing package version cannot be edited');
select throws_ok($$delete from platform_private.resource_access_settings$$,'22023',null,'managed mode cannot be removed to regain legacy access');
select throws_ok($$update platform_private.resource_access_settings set revision=1$$,'22023',null,'authority revisions cannot go backwards');
insert into platform_private.resource_grants(id,project_id,actor_id,package_id,package_version,preset_id,preset_version,purpose,starts_at,expires_at,created_by,approved_by,reason) values('89000000-0000-4000-8000-000000000003','b2000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000001',1,'89000000-0000-4000-8000-000000000002',1,'research',now(),now()+interval '1 day','10000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000005','Synthetic approved resource use');
select throws_ok($$update platform_private.resource_grants set expires_at=now()+interval '100 days'$$,'22023',null,'grant expiry cannot be silently extended');
select throws_ok($$insert into platform_private.resource_grants(project_id,actor_id,package_id,package_version,preset_id,preset_version,purpose,starts_at,expires_at,created_by,approved_by,reason) select project_id,actor_id,package_id,package_version,preset_id,preset_version,purpose,starts_at,starts_at+interval '31 days',created_by,approved_by,reason from platform_private.resource_grants$$,'23514',null,'preset maximum duration is enforced by storage');
select throws_ok($$insert into platform_private.resource_grants(project_id,actor_id,package_id,package_version,preset_id,preset_version,purpose,starts_at,expires_at,created_by,approved_by,reason) select project_id,actor_id,package_id,package_version,preset_id,preset_version,purpose,starts_at,expires_at,created_by,actor_id,reason from platform_private.resource_grants$$,'23514',null,'the target cannot approve its own resource grant');
insert into platform_private.resource_revocations(grant_id,project_id,revoked_by,reason) values('89000000-0000-4000-8000-000000000003','b2000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000005','Synthetic local revocation');
select is((select count(*) from platform_private.resource_grants),1::bigint,'revocation retains original grant');
select is((select revision from platform_private.resource_access_settings),5::bigint,'grant and revocation advance the live policy revision');
select throws_ok($$delete from platform_private.resource_revocations$$,'22023',null,'a revoked grant cannot be revived by deleting history');
set local role authenticated;
select throws_ok($$select * from platform_private.resource_grants$$,'42501',null,'authenticated browser role cannot read authority tables');
reset role;
set local role service_role;
select throws_ok($$select * from platform_private.resource_grants$$,'42501',null,'generic service role cannot bypass the business API');
reset role;
select * from finish();
rollback;
